hunks/0b6f_zxj9ay~6.js\",\"/_next/static/chunks/143cg6c13uly6.js\",\"/_next/static/chunks/07vk.k35-e~ti.js\",\"/_next/static/chunks/0j6k6n9cniknh.js\",\"/_next/static/chunks/0.zxv9arc6a56.js\",\"/_next/static/chunks/00-zmo-3n1bt8.js\",\"/_next/static/chunks/0p4z5tusn0jt6.js\",\"/_next/static/chunks/01mcazkjru_is.js\"],\"default\"]\n6:[\"$\",\"$L22\",null,{\"pageId\":3564,\"activeView\":{\"name\":\"default\",\"activeViewSuffix\":\"\",\"language\":\"en\"},\"children\":\"$@23\"}]\n9:null\ne:[[\"$\",\"title\",\"0\",{\"children\":\"Bhagavad-gītā As It Is 12.13-14\"}],[\"$\",\"meta\",\"1\",{\"name\":\"description\",\"content\":\"Srila Prabhupada''s books online\"}],[\"$\",\"meta\",\"2\",{\"name\":\"application-name\",\"content\":\"Vedabase\"}],[\"$\",\"link\",\"3\",{\"rel\":\"author\",\"href\":\"https://vedabase.io\"}],[\"$\",\"meta\",\"4\",{\"name\":\"author\",\"content\":\"A.C. Bhaktivedanta Swami - Srila Prabhupada\"}],[\"$\",\"meta\",\"5\",{\"name\":\"keywords\",\"content\":\"Srila Prabhupada,Krsna,Krishna,bhakti,devotion\"}],[\"$\",\"meta\",\"6\",{\"name\":\"creator\",\"content\":\"Prahlad Nrsimha das\"}]]\n"])self.__next_f.push([1,"25:T988,"])self.__next_f.push([1,"Coming again to the point of pure devotional service, the Lord is describing the transcendental qualifications of a pure devotee in these two verses. A pure devotee is never disturbed in any circumstances. Nor is he envious of anyone. Nor does a devotee become his enemy’s enemy; he thinks, “This person is acting as my enemy due to my own past misdeeds. So it is better to suffer than to protest.” In the Śrīmad-Bhāgavatam (10.14.8) it is stated: tat te ’nukampāṁ su-samīkṣamāṇo bhuñjāna evātma-kṛtaṁ vipākam. Whenever a devotee is in distress or has fallen into difficulty, he thinks that it is the Lord’s mercy upon him. He thinks, “Thanks to my past misdeeds I should suffer far, far greater than I am suffering now. So it is by the mercy of the Supreme Lord that I am not getting all the punishment I am due. I am just getting a little, by the mercy of the Supreme Personality of Godhead.” Therefore he is always calm, quiet and patient, despite many distressful conditions. A devotee is also always kind to everyone, even to his enemy. Nirmama means that a devotee does not attach much importance to the pains and trouble pertaining to the body because he knows perfectly well that he is not the material body. He does not identify with the body; therefore he is freed from the conception of false ego and is equipoised in happiness and distress. He is tolerant, and he is satisfied with whatever comes by the grace of the Supreme Lord. He does not endeavor much to achieve something with great difficulty; therefore he is always joyful. He is a completely perfect mystic because he is fixed in the instructions received from the spiritual master, and because his senses are controlled he is determined. He is not swayed by false arguments, because no one can lead him from the fixed determination of devotional service. He is fully conscious that Kṛṣṇa is the eternal Lord, so no one can disturb him. All these qualifications enable him to fix his mind and intelligence entirely on the Supreme Lord. Such a standard of devotional service is undoubtedly very rare, but a devotee becomes situated in that stage by following the regulative principles of devotional service. Furthermore, the Lord says that such a devotee is very dear to Him, for the Lord is always pleased with all his activities in full Kṛṣṇa consciousness."])self.__next_f.push([1,"23:[\"$\",\"div\",null,{\"className\":\"flex flex-col min-h-screen text-vb-normal-text\",\"children\":[[\"$\",\"$L1a\",null,{\"className\":\"w-full left-0 z-30 bg-vb-body/95\",\"children\":[\"$\",\"$L1b\",null,{\"mainMenu\":\"$L24\",\"page\":{\"id\":3564,\"meta\":{\"type\":\"books.Verse\",\"slug\":\"13-14\",\"show_in_menus\":false,\"seo_title\":\"\",\"search_description\":\"\",\"first_published_at\":null,\"alias_of\":null,\"locale\":\"en\"},\"title\":\"TEXT