सन्तुष्ट: सततं योगी यतात्मा दृढनिश्चय: ।
मय्यर्पितमनोबुद्धिर्यो मद्भ‍क्त: स मे प्रिय: ॥ १४ ॥\"}]},{\"section\":\"verse_text\",\"section_title\":\"Books.Verse.verse-text\",\"children\":[{\"type\":\"content.Record\",\"title\":\"verse_text\",\"id\":3566,\"bb\":3142,\"url_path\":\"/en/library/bg/12/13-14/b3142/\",\"body_value\":\"adveṣṭā sarva-bhūtānāṁ
maitraḥ karuṇa eva ca
nirmamo nirahaṅkāraḥ
sama-duḥkha-sukhaḥ kṣamī\"},{\"type\":\"content.Record\",\"title\":\"verse_text\",\"id\":3567,\"bb\":3143,\"url_path\":\"/en/library/bg/12/13-14/b3143/\",\"body_value\":\"santuṣṭaḥ satataṁ yogī
yatātmā dṛḍha-niścayaḥ
mayy arpita-mano-buddhir
yo mad-bhaktaḥ sa me priyaḥ\"}]},{\"section\":\"synonyms\",\"section_title\":\"Books.Verse.synonyms\",\"children\":[{\"type\":\"books.Synonyms\",\"title\":\"synonyms\",\"id\":3568,\"bb\":3144,\"url_path\":\"/en/library/bg/12/13-14/b3144/\",\"shadow_value\":\"adveṣṭā – nonenvious; sarva-bhūtānām – toward all living entities; maitraḥ – friendly; karuṇaḥ – kindly; eva – certainly; ca – also; nirmamaḥ – with no sense of proprietorship; nirahaṅkāraḥ – without false ego; sama – equal; duḥkha – in distress; sukhaḥ – and happiness; kṣamī – forgiving; santuṣṭaḥ – satisfied; satatam – always; yogī – one engaged in devotion; yata-ātmā – self-controlled; dṛḍha-niścayaḥ – with determination; mayi – upon Me; arpita – engaged; manaḥ – mind; buddhiḥ – and intelligence; yaḥ – one who; mat-bhaktaḥ – My devotee; saḥ – he; me – to Me; priyaḥ – dear.\",\"word_for_word_value\":[{\"word\":\"adveṣṭā\",\"translation\":\"nonenvious\"},{\"word\":\"sarva-bhūtānām\",\"translation\":\"toward all living entities\"},{\"word\":\"maitraḥ\",\"translation\":\"friendly\"},{\"word\":\"karuṇaḥ\",\"translation\":\"kindly\"},{\"word\":\"eva\",\"translation\":\"certainly\"},{\"word\":\"ca\",\"translation\":\"also\"},{\"word\":\"nirmamaḥ\",\"translation\":\"with no sense of proprietorship\"},{\"word\":\"nirahaṅkāraḥ\",\"translation\":\"without false ego\"},{\"word\":\"sama\",\"translation\":\"equal\"},{\"word\":\"duḥkha\",\"translation\":\"in distress\"},{\"word\":\"sukhaḥ\",\"translation\":\"and happiness\"},{\"word\":\"kṣamī\",\"translation\":\"forgiving\"},{\"word\":\"santuṣṭaḥ\",\"translation\":\"satisfied\"},{\"word\":\"satatam\",\"translation\":\"always\"},{\"word\":\"yogī\",\"translation\":\"one engaged in devotion\"},{\"word\":\"yata-ātmā\",\"translation\":\"self-controlled\"},{\"word\":\"dṛḍha-niścayaḥ\",\"translation\":\"with determination\"},{\"word\":\"mayi\",\"translation\":\"upon Me\"},{\"word\":\"arpita\",\"translation\":\"engaged\"},{\"word\":\"manaḥ\",\"translation\":\"mind\"},{\"word\":\"buddhiḥ\",\"translation\":\"and intelligence\"},{\"word\":\"yaḥ\",\"translation\":\"one who\"},{\"word\":\"mat-bhaktaḥ\",\"translation\":\"My devotee\"},{\"word\":\"saḥ\",\"translation\":\"he\"},{\"word\":\"me\",\"translation\":\"to Me\"},{\"word\":\"priyaḥ\",\"translation\":\"dear\"}]}]},{\"section\":\"translation\",\"section_title\":\"Books.Verse.translation\",\"children\":[{\"type\":\"content.Record\",\"title\":\"translation\",\"id\":3569,\"bb\":3145,\"url_path\":\"/en/library/bg/12/13-14/b3145/\",\"body_value\":\"One who is not envious but is a kind friend to all living entities, who does not think himself a proprietor and is free from false ego, who is equal in both happiness and distress, who is tolerant, always satisfied, self-controlled, and engaged in devotional service with determination, his mind and intelligence fixed on Me – such a devotee of Mine is very dear to Me.\"}]},{\"section\":\"purport\",\"section_title\":\"Books.Verse.purport\",\"children\":[{\"type\":\"content.Record\",\"title\":\"paragraph\",\"id\":3570,\"bb\":3146,\"url_path\":\"/en/library/bg/12/13-14/b3146/\",\"body_value\":\"$25\"}]}],\"short_title\":\"Bg. 12.13-14\",\"medium_title\":\"Bhagavad-gītā As It Is 12.13-14\"},\"locale\":\"en\",\"activeView\":\"$6:props:activeView\"}]}],\"$L26\",\"$L27\",\"$L28\"]}]\n"])self.__next_f.push([1,"2a:I[83068,[\"/_next/static/chunks/130enlymdm.jk.js\",\"/_next/static/chunks/0b6f_zxj9ay~6.js\",\"/_next/static/chunks/143cg6c13uly6.js\",\"/_next/static/chunks/07vk.k35-e~ti.js\",\"/_next/static/chunks/0j6k6n9cniknh.js\",\"/_next/static/chunks/0.zxv9arc6a56.js\",\"/_next/static/chunks/00-zmo-3n1bt8.js\",\"/_next/static/chunks/0p4z5tusn0jt6.js\",\"/_next/static/chunks/01mcazkjru_is.js\"],\"default\"]\n30:I[78455,[\"/_next/static/chunks/130enlymdm.jk.js\",\"/_next/static/chunks/0b6f_zxj9ay~6.js\",\"/_next/static/chunks/143cg6c13uly6.js\",\"/_next/static/chunks/07vk.k35-e~ti.js\",\"/_next/static/chunks/0j6k6n9cniknh.js\",\"/_next/static/chunks/0.zxv9arc6a56.js